2.25.1

        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug was caused by improper management of floating objects in the context, leading to a crash when these objects were not correctly unregistered or closed. This was likely due to the absence of calls to unregister floating objects in the finalizer and the direct closure of objects without invoking Ruby's method, which could bypass necessary cleanup processes.

        Commit message:
        accessor: use floating object mechanism

It fixes a crash bug that is introduced at
5976731352ed992ed3b6c4c0434e9ffccc03477c.

Reported by cosmo0920. Thanks!!!  

        Patch:
          */
 VALUE
 rb_grn_table_get_column (VALUE self, VALUE rb_name)
 {
     grn_user_data *user_data;
     grn_ctx *context = NULL;
     grn_obj *table;
     grn_obj *column;
     const char *name = NULL;
     unsigned name_size = 0;
     grn_bool owner;
     VALUE rb_column;
     VALUE columns;
     VALUE *raw_columns;
     long i, n;

     rb_grn_table_deconstruct(SELF(self), &table, &context,
                              NULL, NULL,
                              NULL, NULL, NULL,
                              &columns);

     ruby_object_to_column_name(rb_name, &name, &name_size);
     raw_columns = RARRAY_PTR(columns);
     n = RARRAY_LEN(columns);
     for (i = 0; i < n; i++) {
         VALUE rb_column = raw_columns[i];
         RbGrnNamedObject *rb_grn_named_object;

         rb_grn_named_object = RB_GRN_NAMED_OBJECT(DATA_PTR(rb_column));
         if (name_size == rb_grn_named_object->name_size &&
             memcmp(name, rb_grn_named_object->name, name_size) == 0) {
             return rb_column;
         }
     }

     column = grn_obj_column(context, table, name, name_size);
     rb_grn_context_check(context, self);
     if (!column)
         return Qnil;

     user_data = grn_obj_user_data(context, column);
     if (user_data) {
         RbGrnObject *rb_grn_object;
         rb_grn_object = user_data->ptr;
         if (rb_grn_object) {
             rb_ary_push(columns, rb_grn_object->self);
             return rb_grn_object->self;
         }
     }

     owner = column->header.type == GRN_ACCESSOR;
     rb_column = GRNCOLUMN2RVAL(Qnil, context, column, owner);
     if (owner) {
-        rb_iv_set(rb_column, "table", self);
+        rb_grn_context_register_floating_object(DATA_PTR(rb_column));
     }
     rb_grn_named_object_set_name(RB_GRN_NAMED_OBJECT(DATA_PTR(rb_column)),
                                  name, name_size);

     return rb_column;
 }



